template:
struct Parser⟦g_struct⟧ {
    source: ⟦ty_field⟧,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> &'a str {
        self.source
    }
}

fn main() {
    let doc = String::from("hello");
    let p = Parser { source: &doc };
    println!("{}", p.peek());
}

tests:
#[test]
fn parses_peek() {
    let doc = String::from("hello");
    let p = Parser { source: &doc };
    assert_eq!(p.peek(), "hello");
}
